def cmp(a,b):
    return abs(a-b)<1e-9
from fractions import Fraction
import math
res=math.sqrt(1+Fraction(1,3)**2) if False else math.sqrt(1+(1/3)**2)
opts=[math.sqrt(3)/3,2*math.sqrt(2)/3,math.sqrt(10)/3,math.sqrt(10)/9]
idx='ABCD'.index('C')
assert cmp(res,opts[idx])
for i,o in enumerate(opts):
    if i!=idx: assert not cmp(res,o)
